#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_17 17
#define GPIO_LINE_18 18

static struct gpiod_line *line_17, *line_18;

static void cleanup(void)
{
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
}

int main(void)
{
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line_17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    if (!line_17) {
        fprintf(stderr, "Failed to get line %u: %s\n",
                GPIO_LINE_17, strerror(errno));
        ret = EXIT_FAILURE;
        goto out_close_chip;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line_18) {
        fprintf(stderr, "Failed to get line %u: %s\n",
                GPIO_LINE_18, strerror(errno));
        ret = EXIT_FAILURE;
        goto out_release_line_17;
    }

    ret = gpiod_line_request_output(line_17, "app", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %u: %s\n",
                GPIO_LINE_17, strerror(-ret));
        ret = EXIT_FAILURE;
        goto out_release_line_18;
    }

    ret = gpiod_line_request_output(line_18, "app", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %u: %s\n",
                GPIO_LINE_18, strerror(-ret));
        ret = EXIT_FAILURE;
        goto out_release_line_17;
    }

    printf("GPIO %u set to 0\n", GPIO_LINE_17);
    printf("GPIO %u set to 1\n", GPIO_LINE_18);

    atexit(cleanup);

    return EXIT_SUCCESS;

out_release_line_18:
    gpiod_line_release(line_18);
out_release_line_17:
    gpiod_line_release(line_17);
out_close_chip:
    gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    int pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pin_mode(pi, 18, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 18 to output mode.\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    signal(SIGINT, interrupt_handler);

    while (!stop) {
        if (gpio_write(pi, 18, 1) < 0) {
            printf("Failed to set GPIO 18 high.\n");
            pigpio_stop(pi);
            return EXIT_FAILURE;
        }
        printf("GPIO 18 set to high.\n");

        sleep(500);

        if (gpio_write(pi, 18, 0) < 0) {
            printf("Failed to set GPIO 18 low.\n");
            pigpio_stop(pi);
            return EXIT_FAILURE;
        }
        printf("GPIO 18 set to low.\n");

        sleep(500);
    }

    if (gpio_write(pi, 18, 0) < 0) {
        printf("Failed to set GPIO 18 low.\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define MAX_CHECKS 10

struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;

void cleanup_and_exit(int code)
{
    if (echo_line)
        gpiod_line_release(echo_line);
    if (trigger_line)
        gpiod_line_release(trigger_line);
    if (chip)
        gpiod_chip_close(chip);
    exit(code);
}

int main(void)
{
    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %m\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line: %m\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        fprintf(stderr, "Failed to request trigger line: %m\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line: %m\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        fprintf(stderr, "Failed to request echo line: %m\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        // Send trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        int count = 0;
        while (gpiod_line_get_value(echo_line) == 0 && count++ < MAX_CHECKS)
            usleep(10000);

        if (count >= MAX_CHECKS) {
            fprintf(stderr, "Echo line did not become high, device not responding\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        // Wait for echo pulse
        count = 0;
        while (gpiod_line_get_value(echo_line) == 1 && count++ < MAX_CHECKS)
            usleep(10000);

        if (count >= MAX_CHECKS) {
            fprintf(stderr, "Echo line did not become low, device not responding\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        printf("Distance measured: %d cm\n", count);
        sleep(60);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

