#include <linux/i2c-dev.h>

#define ADS1115_ADDRESS 0x28
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_DEFAULT 0x8583

#define ADS1115_POLL_DELAY 5

int main() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Unable to open i2c device");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Unable to set slave address");
        return EXIT_FAILURE;
    }

    uint16_t config = ADS1115_CONFIG_DEFAULT;
    if (write(fd, &config, 2) != 2) {
        perror("Unable to write to device");
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t data;
        if (read(fd, &data, 2) != 2) {
            perror("Unable to read from device");
            return EXIT_FAILURE;
        }

        int16_t value = (int16_t)data;
        if (value >= -2048 && value <= 2047) {
            printf("Reading: %d\n", value);
        } else {
            fprintf(stderr, "Invalid reading: %d\n", value);
        }

        sleep(ADS1115_POLL_DELAY);
    }

    close(fd);
    return EXIT_SUCCESS;
}

