#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40

int main() {
    int file;
    unsigned char buffer[2];
    int rc;

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Unable to open I2C device");
        return EXIT_FAILURE;
    }

    rc = ioctl(file, I2C_SLAVE, SI7021_ADDR);
    if (rc < 0) {
        perror("Unable to set I2C slave");
        return EXIT_FAILURE;
    }

    while (1) {
        buffer[0] = 0xE5;
        buffer[1] = 0x00;

        rc = write(file, buffer, 2);
        if (rc < 0) {
            perror("Unable to write to I2C device");
            return EXIT_FAILURE;
        }

        usleep(10000);

        rc = read(file, buffer, 2);
        if (rc < 0) {
            perror("Unable to read from I2C device");
            return EXIT_FAILURE;
        }

        int humidity = (buffer[0] << 8) | buffer[1];
        if (humidity < 0 || humidity > 10000) {
            fprintf(stderr, "Invalid humidity reading: %d\n", humidity);
            continue;
        }

        printf("Humidity: %.2f%%\n", (float)humidity / 100.0);

        sleep(5);
    }

    close(file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
