#include <linux/i2c-dev.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

int main() {
    int file;
    char buffer[2];
    int ret;

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Unable to open i2c device");
        return EXIT_FAILURE;
    }

    ret = ioctl(file, I2C_SLAVE, ADS1115_ADDRESS);
    if (ret < 0) {
        perror("Unable to set i2c slave");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        buffer[0] = ADS1115_REG_CONFIG;
        ret = write(file, buffer, 1);
        if (ret < 0) {
            perror("Unable to write to i2c device");
            return EXIT_FAILURE;
        }

        buffer[0] = ADS1115_REG_CONVERSION;
        ret = write(file, buffer, 1);
        if (ret < 0) {
            perror("Unable to write to i2c device");
            return EXIT_FAILURE;
        }

        ret = read(file, buffer, 2);
        if (ret < 0) {
            perror("Unable to read from i2c device");
            return EXIT_FAILURE;
        }

        printf("Reading %d: %d\n", i, (buffer[0] << 8) | buffer[1]);

        sleep(1);
    }

    close(file);

    return EXIT_SUCCESS;
}

