#include <errno.h>
#include <gpiod.h>

#define MAX_CYCLES 256

static struct gpiod_line *lines[6];
static struct gpiod_chip *chip;

void cleanup(void)
{
    for (int i = 0; i < 6; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
}

int main(void)
{
    int ret, i, val;
    unsigned int offsets[6] = { 8, 9, 10, 11, 23, 24 };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < 6; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n",
                    offsets[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(lines[i], "my-program", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %u: %s\n",
                    offsets[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < MAX_CYCLES; i++) {
        val = i % 2;
        for (int j = 0; j < 6; j++) {
            ret = gpiod_line_set_value(lines[j], val);
            if (ret < 0) {
                fprintf(stderr, "Failed to set line %u: %s\n",
                        offsets[j], strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Set GPIO %u to %d\n", offsets[j], val);
        }
        sleep(1);
    }

    cleanup();
