#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line;

void cleanup(void)
{
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
}

int main(void)
{
    int ret;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto err_close_chip;
    }

    ret = gpiod_line_request_output(trigger_line, "hc-sr04", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        ret = EXIT_FAILURE;
        goto err_release_trigger;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto err_release_trigger;
    }

    ret = gpiod_line_request_input(echo_line, "hc-sr04");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        ret = EXIT_FAILURE;
        goto err_release_echo;
    }

    atexit(cleanup);

    while (1) {
        /* Fire the trigger */
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        /* Wait for the echo */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 10000000 };
        ret = gpiod_line_wait_for_rising_edge(echo_line, &ts);
        if (ret < 0) {
            perror("gpiod_line_wait_for_rising_edge");
            ret = EXIT_FAILURE;
            goto err_release_echo;
        }

        /* Measure the echo */
        unsigned int echo_duration = gpiod_line_get_value(echo_line);
        printf("Echo duration: %u\n", echo_duration);

        /* Sleep for a second */
        sleep(1);
    }

err_release_echo:
    gpiod_line_release(echo_line);
err_release_trigger:
    gpiod_line_release(trigger_line);
err_close_chip:
    gpiod_chip_close(chip);

    return ret;
}

