#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDRESS 0x44
#define OPT3001_REG_CONFIGURATION 0x01
#define OPT3001_REG_LOW_LIMIT 0x02
#define OPT3001_REG_HIGH_LIMIT 0x03
#define OPT3001_REG_MANUAL_GAIN 0x06
#define OPT3001_REG_RESULT 0x00

static int i2c_file;

static int i2c_write_word(int file, int addr, __u8 reg, __u16 value) {
    unsigned char buffer[3];
    buffer[0] = reg;
    buffer[1] = value >> 8;
    buffer[2] = value & 0xff;
    if (write(file, buffer, 3) != 3) {
        perror("i2c_write_word: write");
        return -1;
    }
    return 0;
}

static int i2c_read_word(int file, int addr, __u8 reg, __u16 *value) {
    unsigned char buffer[2];
    if (write(file, &reg, 1) != 1) {
        perror("i2c_read_word: write");
        return -1;
    }
    if (read(file, buffer, 2) != 2) {
        perror("i2c_read_word: read");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

static void exit_handler(int sig) {
    close(i2c_file);
    exit(0);
}

int main() {
    __u16 value;

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, OPT3001_ADDRESS) < 0) {
        perror("ioctl");
        return 1;
    }

    atexit(exit_handler);

    if (i2c_read_word(i2c_file, OPT3001_ADDRESS, OPT3001_REG_RESULT, &value) < 0) {
        return 1;
    }

    printf("Reading: 0x%04x\n", value);

    close(i2c_file);

    return 0;
}

