#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>

#define DEVICE_PATH "/dev/ttyAMA0"

int fd;

void exit_handler(int signum) {
    tcflush(fd, TCIOFLUSH);
    close(fd);
    exit(signum);
}

int main() {
    struct termios options;

    fd = open(DEVICE_PATH, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening device: %s\n", DEVICE_PATH);
        exit(EXIT_FAILURE);
    }

    if (tcgetattr(fd, &options) < 0) {
        fprintf(stderr, "Error getting port settings\n");
        exit_handler(EXIT_FAILURE);
    }

    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        fprintf(stderr, "Error setting port settings\n");
        exit_handler(EXIT_FAILURE);
    }

    signal(SIGINT, exit_handler);

    char buffer[100];
    ssize_t n;

    while ((n = read(fd, buffer, sizeof(buffer))) > 0) {
        buffer[n] = '\0';
        printf("%s", buffer);
        fflush(stdout);
    }

    if (n == -1) {
        fprintf(stderr, "Error reading from device\n");
        exit_handler(EXIT_FAILURE);
    }

    exit_handler(EXIT_SUCCESS);
}

