#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

// GPIO pins to use
#define GPIO4 4
#define GPIO12 12
#define GPIO18 18

// PWM frequency in Hz
#define PWM_FREQ 1000

// PWM duty cycle in microseconds
#define PWM_DUTY_CYCLE_MIN 500
#define PWM_DUTY_CYCLE_MAX 2500

// Global variable to control the loop
volatile sig_atomic_t keep_running = 1;

// Signal handler for clean exit
void sigint_handler(int signo) {
    keep_running = 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, sigint_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO as PWM
    if (gpioSetMode(GPIO4, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO12, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    // Set PWM frequency and duty cycle
    if (gpioSetPWMfrequency(GPIO4, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GPIO12, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GPIO18, PWM_FREQ) < 0 ||
        gpioSetPWMdutycycle(GPIO4, PWM_DUTY_CYCLE_MIN) < 0 ||
        gpioSetPWMdutycycle(GPIO12, PWM_DUTY_CYCLE_MIN) < 0 ||
        gpioSetPWMdutycycle(GPIO18, PWM_DUTY_CYCLE_MIN) < 0) {
        fprintf(stderr, "Failed to set PWM\n");
        return 1;
    }

    // Main loop
    while (keep_running) {
        printf("PWM on GPIO4, GPIO12, GPIO18 with duty cycle %d\n", PWM_DUTY_CYCLE_MIN);
        sleep(1);
    }

    // Clean up
    gpioSetPWMdutycycle(GPIO4, 0);
    gpioSetPWMdutycycle(GPIO12, 0);
    gpioSetPWMdutycycle(GPIO18, 0);
    gpioTerminate();

    return 0;
}

