            fprintf(stderr, "Failed to read DS18B20: %s\n", strerror(errno));
            exit_code = EXIT_FAILURE;
            break;
        }

        buf[bytes_read] = '\0';

        char *temp_str = strstr(buf, "t=");
        if (temp_str == NULL) {
            fprintf(stderr, "Failed to find temperature in DS18B20 response\n");
            exit_code = EXIT_FAILURE;
            break;
        }

        temp_str += 2;
        long temp_milli = strtol(temp_str, NULL, 10);
        if (errno == ERANGE) {
            fprintf(stderr, "Temperature reading is out of range\n");
            exit_code = EXIT_FAILURE;
            break;
        }

        printf("Temperature: %.2f C\n", (double)temp_milli / 1000.0);

        sleep(5);
    }

    close(fd);

    return exit_code;
}

