#define HTU21D_READ_TEMP 0xE3
#define HTU21D_READ_HUMIDITY 0xE5

#define HTU21D_TEMP_MIN -40.0
#define HTU21D_TEMP_MAX 125.0
#define HTU21D_HUMIDITY_MIN 0.0
#define HTU21D_HUMIDITY_MAX 100.0

int main() {
    int i2c_dev = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_dev < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_dev, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_dev);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t cmd = HTU21D_READ_TEMP;
        if (write(i2c_dev, &cmd, sizeof(cmd)) != sizeof(cmd)) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            close(i2c_dev);
            return EXIT_FAILURE;
        }

        uint16_t data;
        if (read(i2c_dev, &data, sizeof(data)) != sizeof(data)) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            close(i2c_dev);
            return EXIT_FAILURE;
        }

        float temp = ((data >> 2) * 175.72) / 65536.0 - 46.85;
        if (temp < HTU21D_TEMP_MIN || temp > HTU21D_TEMP_MAX) {
            fprintf(stderr, "Invalid temperature reading: %.2f\n", temp);
            continue;
        }

        cmd = HTU21D_READ_HUMIDITY;
        if (write(i2c_dev, &cmd, sizeof(cmd)) != sizeof(cmd)) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            close(i2c_dev);
            return EXIT_FAILURE;
        }

        if (read(i2c_dev, &data, sizeof(data)) != sizeof(data)) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            close(i2c_dev);
            return EXIT_FAILURE;
        }

        float humidity = ((data >> 2) * 100.0) / 65536.0;
        if (humidity < HTU21D_HUMIDITY_MIN || humidity > HTU21D_HUMIDITY_MAX) {
            fprintf(stderr, "Invalid humidity reading: %.2f\n", humidity);
            continue;
        }

        printf("Temperature: %.2f C, Humidity: %.2f%%\n", temp, humidity);

        sleep(60);
    }

    close(i2c_dev);
    return EXIT_SUCCESS;
}

