int main(void)
{
    int fd, ret;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Could not open video device");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = x;
    fmt.fmt.pix.height = y;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_BGR24;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Could not set format");
        goto error;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("Could not queue buffer");
        goto error;
    }

    ret = ioctl(fd, VIDIOC_TRY_PREVIEW, NULL);
    if (ret < 0) {
        perror("Could not start capture");
        goto error;
    }

    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("Could not dequeue buffer");
        goto error;
    }

    ret = write(STDOUT_FILENO, buf.m.planes[0].m.mem_offset, x * y * 3);
    if (ret < 0) {
        perror("Could not write image");
        goto error;
    }

    ret = ioctl(fd, VIDIOC_STOP_PREVIEW, NULL);
    if (ret < 0) {
        perror("Could not stop capture");
        goto error;
    }

    close(fd);
    return EXIT_SUCCESS;

error:
    close(fd);
    return EXIT_FAILURE;
}

