#define BME280_ADDR 0x76

#define REG_CTRL_HUM 0xF2
#define REG_CTRL_MEAS 0xF4
#define REG_CONFIG 0xF5
#define REG_TEMP_XLSB 0xFC
#define REG_TEMP_LSB 0xFB
#define REG_TEMP_MSB 0xFA
#define REG_HUMIDITY_LSB 0xFD
#define REG_HUMIDITY_MSB 0xFC

int main() {
    int file;
    int ret;
    char buf[3];

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    ret = ioctl(file, I2C_SLAVE, BME280_ADDR);
    if (ret < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    buf[0] = REG_CTRL_HUM;
    buf[1] = 0x01;
    ret = write(file, buf, 2);
    if (ret < 0) {
        perror("write");
        return EXIT_FAILURE;
    }

    buf[0] = REG_CTRL_MEAS;
    buf[1] = 0x27;
    ret = write(file, buf, 2);
    if (ret < 0) {
        perror("write");
        return EXIT_FAILURE;
    }

    buf[0] = REG_CONFIG;
    buf[1] = 0x00;
    ret = write(file, buf, 2);
    if (ret < 0) {
        perror("write");
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(5);

        buf[0] = REG_TEMP_XLSB;
        ret = write(file, buf, 1);
        if (ret < 0) {
            perror("write");
            return EXIT_FAILURE;
        }

        ret = read(file, buf, 3);
        if (ret < 0) {
            perror("read");
            return EXIT_FAILURE;
        }

        int32_t temperature = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
        temperature = temperature / 16;

        buf[0] = REG_HUMIDITY_LSB;
        ret = write(file, buf, 1);
        if (ret < 0) {
            perror("write");
            return EXIT_FAILURE;
        }

        ret = read(file, buf, 2);
        if (ret < 0) {
            perror("read");
            return EXIT_FAILURE;
        }

        int32_t humidity = (buf[0] << 8) | buf[1];

        printf("Temperature: %d\n", temperature);
        printf("Humidity: %d\n", humidity);
    }

    close(file);
    return EXIT_SUCCESS;
}

