#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 22
#define DISTANCE_GPIO 27

struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;

void cleanup(void)
{
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
}

int main(void)
{
    int ret;
    struct timespec start, end;
    long diff;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = gpiod_line_request_output(trigger_line, "hc-sr04", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = gpiod_line_request_input(echo_line, "hc-sr04");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    while (1) {
        /* Send trigger pulse */
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        /* Wait for echo pulse */
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            diff = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (diff > 20000) {
                fprintf(stderr, "Echo pulse not received\n");
                goto cleanup;
            }
        }

        /* Measure echo pulse */
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            diff = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (diff > 20000) {
                fprintf(stderr, "Echo pulse not received\n");
                goto cleanup;
            }
        }

        /* Calculate distance */
        diff /= 2;
        if (diff < 2000 || diff > 80000) {
            fprintf(stderr, "Invalid distance measurement: %ld\n", diff);
            goto cleanup;
        }
        printf("Distance: %ld\n", diff);

        usleep(100000);
    }

cleanup:
    cleanup();
    return ret;
}

