#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <paho-mqtt/MQTTClient.h>

#define SENSOR_GPIO 21
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/data"

struct gpiod_line *sensor_line;
struct gpiod_chip *sensor_chip;

void cleanup(void) {
    if (sensor_line)
        gpiod_line_release(sensor_line);
    if (sensor_chip)
        gpiod_chip_close(sensor_chip);
}

int main(void) {
    int ret;
    int sensor_value;
    MQTTClient mqtt_client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    sensor_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!sensor_chip) {
        fprintf(stderr, "Failed to open 'gpiochip0'\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(sensor_chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get line %d\n", SENSOR_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = gpiod_line_request_input(sensor_line, "sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request input\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    sensor_value = gpiod_line_get_value(sensor_line);
    if (sensor_value < 0) {
        fprintf(stderr, "Failed to get sensor value\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = MQTTClient_create(&mqtt_client, MQTT_BROKER, "sensor_client",
                            MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = MQTTClient_connect(mqtt_client, &conn_opts);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    pubmsg.payload = &sensor_value;
    pubmsg.payloadlen = sizeof(sensor_value);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    ret = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    MQTTClient_disconnect(mqtt_client, 1000);

cleanup:
    cleanup();
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    int pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pin_mode(pi, 18, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 18 to output mode.\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    signal(SIGINT, interrupt_handler);

    while (!stop) {
        for (int i = 0; i <= 100; i += 10) {
            if (gpio_pwm_write(pi, 18, i * 100) < 0) {
                printf("Failed to set PWM value.\n");
                pigpio_stop(pi);
                return EXIT_FAILURE;
            }
            printf("Set PWM value to %d%%\n", i);
            sleep(5);
        }
    }

    if (gpio_pwm_write(pi, 18, 0) < 0) {
        printf("Failed to set PWM value to 0.\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line;

void cleanup(void)
{
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
}

int main(void)
{
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    echo_line = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("gpiod_line_request_output");
        goto error;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("gpiod_line_request_input");
        goto error;
    }

    atexit(cleanup);

    while (1) {
        /* Trigger the sensor */
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        /* Wait for the echo */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 200 * 1000 * 1000 };
        if (gpiod_line_wait_for_rising_edge(echo_line, &ts) < 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue;
        }

        /* Read the echo */
        int value = gpiod_line_get_value(echo_line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            continue;
        }

        printf("Echo value: %d\n", value);

        /* Repeat every 200ms */
        usleep(200 * 1000);
    }

    return EXIT_SUCCESS;

error:
    cleanup();
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

// GPIO pins to use
#define GPIO17 17
#define GPIO18 18
#define GPIO22 22
#define GPIO23 23

// PWM frequency in Hz
#define PWM_FREQ 1000

// PWM range
#define PWM_RANGE 1024

// PWM values to cycle through
#define PWM_VALUES {512, 1023, 0, 512}

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon\n");
        return 1;
    }

    int err = gpio_export(pi, GPIO17, 1);
    if (err < 0) {
        printf("Failed to export GPIO17: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_export(pi, GPIO18, 1);
    if (err < 0) {
        printf("Failed to export GPIO18: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_export(pi, GPIO22, 1);
    if (err < 0) {
        printf("Failed to export GPIO22: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_export(pi, GPIO23, 1);
    if (err < 0) {
        printf("Failed to export GPIO23: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_set_mode(pi, GPIO17, PI_OUTPUT);
    if (err < 0) {
        printf("Failed to set GPIO17 to output mode: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_set_mode(pi, GPIO18, PI_OUTPUT);
    if (err < 0) {
        printf("Failed to set GPIO18 to output mode: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_set_mode(pi, GPIO22, PI_OUTPUT);
    if (err < 0) {
        printf("Failed to set GPIO22 to output mode: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_set_mode(pi, GPIO23, PI_OUTPUT);
    if (err < 0) {
        printf("Failed to set GPIO23 to output mode: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_set_pull_up_down(pi, GPIO17, PI_PUD_OFF);
    if (err < 0) {
        printf("Failed to set GPIO17 to no pull-up/down: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_set_pull_up_down(pi, GPIO18, PI_PUD_OFF);
    if (err < 0) {
        printf("Failed to set GPIO18 to no pull-up/down: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_set_pull_up_down(pi, GPIO22, PI_PUD_OFF);
    if (err < 0) {
        printf("Failed to set GPIO22 to no pull-up/down: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_set_pull_up_down(pi, GPIO23, PI_PUD_OFF);
    if (err < 0) {
        printf("Failed to set GPIO23 to no pull-up/down: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_range(pi, GPIO17, PWM_RANGE);
    if (err < 0) {
        printf("Failed to set PWM range for GPIO17: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_range(pi, GPIO18, PWM_RANGE);
    if (err < 0) {
        printf("Failed to set PWM range for GPIO18: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_range(pi, GPIO22, PWM_RANGE);
    if (err < 0) {
        printf("Failed to set PWM range for GPIO22: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_range(pi, GPIO23, PWM_RANGE);
    if (err < 0) {
        printf("Failed to set PWM range for GPIO23: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_freq(pi, GPIO17, PWM_FREQ);
    if (err < 0) {
        printf("Failed to set PWM frequency for GPIO17: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_freq(pi, GPIO18, PWM_FREQ);
    if (err < 0) {
        printf("Failed to set PWM frequency for GPIO18: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_freq(pi, GPIO22, PWM_FREQ);
    if (err < 0) {
        printf("Failed to set PWM frequency for GPIO22: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_freq(pi, GPIO23, PWM_FREQ);
    if (err < 0) {
        printf("Failed to set PWM frequency for GPIO23: %s\n", pigpio_error(err));
        return 1;
    }

    int pwm_values[] = PWM_VALUES;
    int num_pwm_values = sizeof(pwm_values) / sizeof(pwm_values[0]);
    int i = 0;

    signal(SIGINT, signal_handler);

    while (!stop) {
        for (i = 0; i < num_pwm_values && !stop; i++) {
            printf("Setting PWM value to %d\n", pwm_values[i]);

            err = gpio_pwm_write(pi, GPIO17, pwm_values[i]);
            if (err < 0) {
                printf("Failed to set PWM value for GPIO17: %s\n", pigpio_error(err));
                return 1;
            }

            err = gpio_pwm_write(pi, GPIO18, pwm_values[i]);
            if (err < 0) {
                printf("Failed to set PWM value for GPIO18: %s\n", pigpio_error(err));
                return 1;
            }

            err = gpio_pwm_write(pi, GPIO22, pwm_values[i]);
            if (err < 0) {
                printf("Failed to set PWM value for GPIO22: %s\n", pigpio_error(err));
                return 1;
            }

            err = gpio_pwm_write(pi, GPIO23, pwm_values[i]);
            if (err < 0) {
                printf("Failed to set PWM value for GPIO23: %s\n", pigpio_error(err));
                return 1;
            }

            sleep(100);
        }
    }

    err = gpio_pwm_write(pi, GPIO17, 0);
    if (err < 0) {
        printf("Failed to set PWM value for GPIO17: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_write(pi, GPIO18, 0);
    if (err < 0) {
        printf("Failed to set PWM value for GPIO18: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_write(pi, GPIO22, 0);
    if (err < 0) {
        printf("Failed to set PWM value for GPIO22: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_pwm_write(pi, GPIO23, 0);
    if (err < 0) {
        printf("Failed to set PWM value for GPIO23: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_unexport(pi, GPIO17);
    if (err < 0) {
        printf("Failed to unexport GPIO17: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_unexport(pi, GPIO18);
    if (err < 0) {
        printf("Failed to unexport GPIO18: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_unexport(pi, GPIO22);
    if (err < 0) {
        printf("Failed to unexport GPIO22: %s\n", pigpio_error(err));
        return 1;
    }

    err = gpio_unexport(pi, GPIO23);
    if (err < 0) {
        printf("Failed to unexport GPIO23: %s\n", pigpio_error(err));
        return 1;
    }

    pigpio_stop(pi);

    return 0;
}

