    if (gpiod_line_get_value(line, &sensor_value)) {
        perror("gpiod_line_get_value");
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_value < 0 || sensor_value > 1) {
        fprintf(stderr, "Invalid sensor reading: %d\n", sensor_value);
        cleanup();
        return EXIT_FAILURE;
    }

    MQTTClient_publish(client, MQTT_TOPIC, &sensor_value, 1, 0, 0);

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libgpiod.h>
#include <paho-mqtt/MQTTClient.h>
#include <unistd.h>
#include <errno.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CONF_REG 0x01
#define ADS1115_CONF_SETUP 0x8583
#define ADS1115_READ_REG 0x00

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/ads1115"

struct gpiod_device *device;
struct gpiod_line *line;

int ads1115_read(int *val) {
    unsigned char buf[2];
    int ret;

    ret = gpiod_line_read_i2c(line, ADS1115_ADDRESS, ADS1115_READ_REG, buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from ADS1115: %s\n", strerror(errno));
        return ret;
    }

    *val = (buf[0] << 8) | buf[1];
    return 0;
}

void exit_handler(int sig) {
    gpiod_line_release(line);
    gpiod_device_close(device);
    exit(0);
}

int main() {
    int ret, val;
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;

    device = gpiod_device_open("/dev/i2c-1");
    if (!device) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_device_claim_line(device, "ads1115", GPIOD_LINE_REQUEST_DIRECTION_INPUT, ADS1115_ADDRESS);
    if (!line) {
        fprintf(stderr, "Failed to claim line: %s\n", strerror(errno));
        return 1;
    }

    ret = gpiod_line_write_i2c(line, ADS1115_ADDRESS, ADS1115_CONF_REG, &ADS1115_CONF_SETUP, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to ADS1115: %s\n", strerror(errno));
        return 1;
    }

    ret = MQTTClient_create(&client, MQTT_BROKER, "ads1115_publisher", NULL, 0, NULL);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %d\n", ret);
        return 1;
    }

    ret = MQTTClient_connect(client, &conn_opts);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %d\n", ret);
        return 1;
    }

    signal(SIGINT, exit_handler);

    for (int i = 0; i < 10; i++) {
        ret = ads1115_read(&val);
        if (ret < 0)
            return 1;

        pubmsg.payload = &val;
        pubmsg.payloadlen = sizeof(val);
        ret = MQTTClient_publish(client, MQTT_TOPIC, &pubmsg);
        if (ret != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish to MQTT topic: %d\n", ret);
            return 1;
        }

        sleep(1);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpiod_line_release(line);
    gpiod_device_close(device);

    return 0;
}

