#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define BMP280_ADDR 0x76
#define I2C_DEV_PATH "/dev/i2c-1"

int main() {
    int file;
    unsigned char buffer[2];
    struct i2c_rdwr_ioctl_data msg;
    struct i2c_msg msgs[2];

    file = open(I2C_DEV_PATH, O_RDWR);
    if (file < 0) {
        perror("Unable to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Unable to set I2C slave");
        return EXIT_FAILURE;
    }

    while (1) {
        msgs[0].addr = BMP280_ADDR;
        msgs[0].flags = I2C_M_RD;
        msgs[0].len = sizeof(buffer);
        msgs[0].buf = buffer;

        msg.msgs = msgs;
        msg.nmsgs = 1;

        if (ioctl(file, I2C_RDWR, &msg) < 0) {
            perror("Unable to read from I2C device");
            return EXIT_FAILURE;
        }

        printf("Read: 0x%02x%02x\n", buffer[0], buffer[1]);

        sleep(5);
    }

    close(file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

int pi;

void cleanup(int signum) {
    if (pi >= 0) {
        // Release the GPIO
        piGpioInitialise();
    }
    exit(0);
}

int main() {
    // Register cleanup function to handle interrupt signals
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Connect to pigpio daemon
    pi = piGpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to connect to pigpio daemon: %s\n", piStrError(pi));
        return EXIT_FAILURE;
    }

    // Set GPIO 4 as PWM output
    int result = piSetMode(pi, 4, PI_OUTPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set GPIO 4 as PWM output: %s\n", piStrError(result));
        cleanup(0);
        return EXIT_FAILURE;
    }

    // Start PWM on GPIO 4 with a duty cycle of 50%
    result = piSetPWMdutycycle(pi, 4, 50);
    if (result < 0) {
        fprintf(stderr, "Failed to start PWM on GPIO 4: %s\n", piStrError(result));
        cleanup(0);
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO 4 set to 50%% duty cycle\n");

    // Release the GPIO
    cleanup(0);

    return EXIT_SUCCESS;
}

