#include <stdio.h>
#include <stdlib.h>
#include <libgpiod.h>
#include <paho-mqtt/MQTTClient.h>

#define SENSOR_GPIO 4
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/data"

struct gpiod_line *sensor_line;
MQTTClient mqtt_client;

void cleanup(void) {
    gpiod_line_release(sensor_line);
    MQTTClient_destroy(&mqtt_client);
}

int main(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request_config request_config = {
        .flags = GPIOD_LINE_REQUEST_FLAG_INPUT,
        .type = GPIOD_LINE_REQUEST_TYPE_EVENT_FALLING_EDGE,
    };
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto cleanup_chip;
    }

    ret = gpiod_line_request(sensor_line, "sensor-reader", &request_config);
    if (ret < 0) {
        perror("gpiod_line_request");
        ret = EXIT_FAILURE;
        goto cleanup_line;
    }

    ret = MQTTClient_create(&mqtt_client, MQTT_BROKER, "sensor-reader",
                            MQTTCLIENT_PERSISTENCE_NONE, 0);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %d\n", ret);
        ret = EXIT_FAILURE;
        goto cleanup_line;
    }

    ret = MQTTClient_connect(mqtt_client, &conn_opts);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %d\n", ret);
        ret = EXIT_FAILURE;
        goto cleanup_client;
    }

    while (1) {
        ret = gpiod_line_event_wait(sensor_line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            ret = EXIT_FAILURE;
            goto cleanup_client;
        }

        pubmsg.payload = "sensor triggered";
        pubmsg.payloadlen = strlen(pubmsg.payload);
        pubmsg.qos = 0;
        pubmsg.retained = 0;

        ret = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, NULL);
        if (ret != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish MQTT message: %d\n", ret);
            ret = EXIT_FAILURE;
            goto cleanup_client;
        }
    }

cleanup_client:
    MQTTClient_disconnect(mqtt_client, 1000);
cleanup_line:
    gpiod_line_release(sensor_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
