#define GPIO23 23
#define GPIO24 24

// PWM frequency in Hz
#define PWM_FREQ 1000

// PWM duty cycle in microseconds
#define PWM_DUTY_CYCLE 500

// Signal handler to release resources
void sig_handler(int signo) {
    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise piGPIO\n");
        exit(EXIT_FAILURE);
    }

    if (piGpioSetMode(GPIO2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to input mode\n", GPIO2);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetMode(GPIO3, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to input mode\n", GPIO3);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetMode(GPIO18, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to input mode\n", GPIO18);
        exit(EXIT_FAILURE);
