    if (piGpioSetMode(GPIO23, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to input mode\n", GPIO23);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetMode(GPIO24, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to input mode\n", GPIO24);
        exit(EXIT_FAILURE);
    }

    piGpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (piGpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise piGPIO\n");
        exit(EXIT_FAILURE);
    }

    if (piGpioSetMode(GPIO2, PI_PWM_OUTPUT) < 0) {
