        exit(EXIT_FAILURE);
    }

    if (piGpioSetMode(GPIO24, PI_PWM_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d to PWM output mode\n", GPIO24);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetPWMfrequency(GPIO2, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", GPIO2);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetPWMfrequency(GPIO3, PWM_FREQ) < 0) {
