        exit(EXIT_FAILURE);
    }

    if (piGpioSetPWMfrequency(GPIO23, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", GPIO23);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetPWMfrequency(GPIO24, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", GPIO24);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetPWMdutycycle(GPIO2, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO%d\n", GPIO2);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetPWMdutycycle(GPIO3, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO%d\n", GPIO3);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetPWMdutycycle(GPIO18, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO%d\n", GPIO18);
        exit(EXIT_FAILURE);
    }

    if (piGpioSetPWMdutycycle(GPIO23, PWM_DUTY_CYCLE) < 0) {
