        return -1;
    }

    if (gpio_pin_mode(pi, 27, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 27 to output mode\n");
        return -1;
    }

    if (gpio_pwm_range(pi, 17, 100) < 0) {
        printf("Failed to set PWM range for GPIO 17\n");
        return -1;
    }

    if (gpio_pwm_range(pi, 22, 100) < 0) {
        printf("Failed to set PWM range for GPIO 22\n");
        return -1;
    }

    if (gpio_pwm_range(pi, 27, 100) < 0) {
