        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);

    return r;
}

int main(void)
{
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers req;
    int fd, ret;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Couldn't open device");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;

    ret = xioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Couldn't set format");
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = xioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("Couldn't request buffers");
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    ret = xioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("Couldn't query buffer");
        return EXIT_FAILURE;
    }

    ret = xioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("Couldn't queue buffer");
        return EXIT_FAILURE;
    }

    while (1) {
        ret = xioctl(fd, VIDIOC_DQBUF, &buf);
        if (ret < 0) {
            perror("Couldn't dequeue buffer");
            return EXIT_FAILURE;
        }

        FILE *file = fopen(IMAGE_PATH, "wb");
        if (!file) {
            perror("Couldn't open file to write image");
            return EXIT_FAILURE;
        }

        fwrite(buf.m.planes[0].m.mem_offset, 1, buf.m.planes[0].length, file);
        fclose(file);

        ret = xioctl(fd, VIDIOC_QBUF, &buf);
        if (ret < 0) {
            perror("Couldn't requeue buffer");
            return EXIT_FAILURE;
        }

        sleep(1);
    }

    close(fd);

    return EXIT_SUCCESS;
}

