    newtio.c_cflag |= (BAUD_RATE | CS8 | CLOCAL | CREAD);

    if (tcsetattr(fd, TCSANOW, &newtio) < 0) {
        perror("New serial port settings could not be set");
        exit(-1);
    }

    while (1) {
        n = read(fd, buf, sizeof(buf));
        if (n > 0) {
            buf[n] = '\0';
            printf("%s", buf);
