#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    int pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pin_mode(pi, 17, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 17 to output mode.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pin_mode(pi, 18, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 18 to output mode.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pin_mode(pi, 27, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 27 to output mode.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, interrupt_handler);

    while (!stop) {
        if (gpio_pwm(pi, 17, 500) < 0) {
            printf("Failed to set PWM on GPIO 17.\n");
            return EXIT_FAILURE;
        }

        if (gpio_pwm(pi, 18, 1500) < 0) {
            printf("Failed to set PWM on GPIO 18.\n");
            return EXIT_FAILURE;
        }

        if (gpio_pwm(pi, 27, 2500) < 0) {
            printf("Failed to set PWM on GPIO 27.\n");
            return EXIT_FAILURE;
        }

        printf("PWM set on GPIO 17, 18, 27.\n");

        sleep(500);

        if (gpio_pwm(pi, 17, 0) < 0) {
            printf("Failed to unset PWM on GPIO 17.\n");
            return EXIT_FAILURE;
        }

        if (gpio_pwm(pi, 18, 0) < 0) {
            printf("Failed to unset PWM on GPIO 18.\n");
            return EXIT_FAILURE;
        }

        if (gpio_pwm(pi, 27, 0) < 0) {
            printf("Failed to unset PWM on GPIO 27.\n");
            return EXIT_FAILURE;
        }

        printf("PWM unset on GPIO 17, 18, 27.\n");

        sleep(500);
    }

    if (pigpio_stop(pi) < 0) {
        printf("Failed to stop pigpio.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

