int main() {
    int fd, ret;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    char *p;
    FILE *file;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("VIDIOC_QUERYCAP");
        goto error;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        goto error;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_G_FMT, &fmt);
    if (ret < 0) {
        perror("VIDIOC_G_FMT");
        goto error;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_QUERYBUF");
        goto error;
    }

    p = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (p == MAP_FAILED) {
        perror("mmap");
        goto error;
    }

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_QBUF");
        goto error_unmap;
    }

    ret = ioctl(fd, VIDIOC_STREAMON, &buf.type);
    if (ret < 0) {
        perror("VIDIOC_STREAMON");
        goto error_unmap;
    }

    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("VIDIOC_DQBUF");
        goto error_streamoff;
    }

    file = fopen(IMAGE_FILE, "wb");
    if (!file) {
        perror("fopen");
        goto error_streamoff;
    }

    fwrite(p, 1, buf.bytesused, file);
    fclose(file);

    ret = ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
    if (ret < 0)
        perror("VIDIOC_STREAMOFF");

    ret = munmap(p, buf.length);
    if (ret < 0) {
        perror("munmap");
        return EXIT_FAILURE;
    }

    close(fd);
    return EXIT_SUCCESS;

error_streamoff:
    ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
error_unmap:
    munmap(p, buf.length);
error:
    close(fd);
    return EXIT_FAILURE;
}

