#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_TRIGGER 17
#define GPIO_ECHO 18
#define DURATION_MS 1000

struct gpiod_chip *chip;
struct gpiod_line *trigger, *echo;

void cleanup(void)
{
    gpiod_line_release(trigger);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
}

int main(void)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    if (!trigger) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    echo = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!echo) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    if (gpiod_line_request_output(trigger, "trigger", 0)) {
        perror("gpiod_line_request_output");
        goto error;
    }

    if (gpiod_line_request_input(echo, "echo")) {
        perror("gpiod_line_request_input");
        goto error;
    }

    atexit(cleanup);

    while (1) {
        /* Trigger the sensor */
        gpiod_line_set_value(trigger, 1);
        usleep(10);
        gpiod_line_set_value(trigger, 0);

        /* Wait for the echo */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = DURATION_MS * 1000000 };
        if (nanosleep(&ts, NULL) != 0) {
            perror("nanosleep");
            goto error;
        }

        /* Read the echo */
        int value = gpiod_line_get_value(echo);
        if (value < 0) {
            perror("gpiod_line_get_value");
            goto error;
        }

        printf("Echo value: %d\n", value);

        /* Repeat every second */
        if (nanosleep(&ts, NULL) != 0) {
            perror("nanosleep");
            goto error;
        }
    }

    return EXIT_SUCCESS;

error:
    cleanup();
    return EXIT_FAILURE;
}

