#include <linux/types.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.raw"

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);

    return r;
}

int main(void)
{
    int fh;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    char *p;
    int i;

    fh = open(DEVICE_NAME, O_RDWR);
    if (fh < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (xioctl(fh, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fh, VIDIOC_G_FMT, &fmt) == -1) {
        perror("VIDIOC_G_FMT");
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fh, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return EXIT_FAILURE;
    }

    p = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fh, buf.m.offset);
    if (p == MAP_FAILED) {
        perror("mmap");
        return EXIT_FAILURE;
    }

    while (1) {
        if (xioctl(fh, VIDIOC_DQBUF, &buf) == -1) {
            perror("VIDIOC_DQBUF");
            return EXIT_FAILURE;
        }

        FILE *f = fopen(IMAGE_FILE, "wb");
        if (f == NULL) {
            perror("fopen");
            return EXIT_FAILURE;
        }

        fwrite(p, 1, buf.bytesused, f);
        fclose(f);

        if (xioctl(fh, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            return EXIT_FAILURE;
        }

        usleep(100000);
    }

    munmap(p, buf.length);
    close(fh);

    return EXIT_SUCCESS;
}

