{
    if (echo_line)
        gpiod_line_release(echo_line);
    if (trigger_line)
        gpiod_line_release(trigger_line);
    if (chip)
        gpiod_chip_close(chip);
}

int main(void)
{
    int ret;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
