#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDR 0x44
#define SHT31_TRIGGER_TEMP_HOLD 0x2B06
#define SHT31_TRIGGER_HUMIDITY_HOLD 0x2C06
#define SHT31_TRIGGER_TEMP_NOHOLD 0x2B0B
#define SHT31_TRIGGER_HUMIDITY_NOHOLD 0x2C0B

#define I2C_DEV_PATH "/dev/i2c-1"

int main() {
    int i2c_file;
    unsigned char buffer[2];
    int status;

    i2c_file = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_file < 0) {
        perror("Could not open i2c device file");
        return EXIT_FAILURE;
    }

    status = ioctl(i2c_file, I2C_SLAVE, SHT31_ADDR);
    if (status < 0) {
        perror("Could not set slave address");
        close(i2c_file);
        return EXIT_FAILURE;
    }

    while (1) {
        // Trigger temperature measurement
        buffer[0] = (SHT31_TRIGGER_TEMP_HOLD >> 8) & 0xFF;
        buffer[1] = SHT31_TRIGGER_TEMP_HOLD & 0xFF;
        status = write(i2c_file, buffer, 2);
        if (status < 0) {
            perror("Could not write to device");
            close(i2c_file);
            return EXIT_FAILURE;
        }

        // Read temperature measurement
        status = read(i2c_file, buffer, 2);
        if (status < 0) {
            perror("Could not read from device");
            close(i2c_file);
            return EXIT_FAILURE;
        }

        // Check measurement validity
        if ((buffer[0] & 0x80) != 0) {
            fprintf(stderr, "Temperature measurement failed its validity check\n");
            close(i2c_file);
            return EXIT_FAILURE;
        }

        // Print temperature measurement
        float temperature = ((buffer[0] & 0x7FFF) * 175.72f / 0x7FFF - 46.85f);
        printf("Temperature: %.2f C\n", temperature);

        // Trigger humidity measurement
        buffer[0] = (SHT31_TRIGGER_HUMIDITY_HOLD >> 8) & 0xFF;
        buffer[1] = SHT31_TRIGGER_HUMIDITY_HOLD & 0xFF;
        status = write(i2c_file, buffer, 2);
        if (status < 0) {
            perror("Could not write to device");
            close(i2c_file);
            return EXIT_FAILURE;
        }

        // Read humidity measurement
        status = read(i2c_file, buffer, 2);
        if (status < 0) {
            perror("Could not read from device");
            close(i2c_file);
            return EXIT_FAILURE;
        }

        // Check measurement validity
        if ((buffer[0] & 0x80) != 0) {
            fprintf(stderr, "Humidity measurement failed its validity check\n");
            close(i2c_file);
            return EXIT_FAILURE;
        }

        // Print humidity measurement
        float humidity = ((buffer[0] & 0x7FFF) * 100.0f / 0x7FFF);
        printf("Humidity: %.2f %%\n", humidity);

        sleep(5);
    }

    close(i2c_file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
