#include <libgpiod.h>

#define GPIO_PINS 10
#define GPIO_OFFSET 5

int main()
{
    struct gpiod_chip *chip;
    struct gpiod_line *line[GPIO_PINS];
    int i;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (i = 0; i < GPIO_PINS; i++) {
        line[i] = gpiod_chip_get_line(chip, i + GPIO_OFFSET);
        if (!line[i]) {
            perror("gpiod_chip_get_line");
            goto close_chip;
        }

        if (gpiod_line_request_output(line[i], "my-program", 1)) {
            perror("gpiod_line_request_output");
            goto release_lines;
        }

        printf("Set GPIO %d to high\n", i + GPIO_OFFSET);
    }

    // Release resources
    for (i = 0; i < GPIO_PINS; i++)
        gpiod_line_release(line[i]);

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

release_lines:
    for (i = 0; i < GPIO_PINS; i++) {
        if (line[i])
            gpiod_line_release(line[i]);
    }

close_chip:
    gpiod_chip_close(chip);

    return EXIT_FAILURE;
}

