#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// GPIO pins to use
#define GPIO17 17
#define GPIO18 18
#define GPIO22 22
#define GPIO27 27

// PWM frequency in Hz
#define PWM_FREQ 1000

// PWM range
#define PWM_RANGE 1024

// PWM duty cycle
#define PWM_DUTY_CYCLE 500

// Signal handler to release resources
void sig_handler(int signo) {
    if (signo == SIGINT) {
        printf("Signal received, releasing resources...\n");
        if (gpioTerminate() < 0) {
            fprintf(stderr, "Error: gpioTerminate failed\n");
        }
        exit(0);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, sig_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    // Set GPIO as PWM
    if (gpioSetMode(GPIO17, PI_MODE_PWM) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO17\n");
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO18, PI_MODE_PWM) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO18\n");
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO22, PI_MODE_PWM) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO22\n");
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO27, PI_MODE_PWM) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO27\n");
        return EXIT_FAILURE;
    }

    // Set PWM frequency and range
    if (gpioSetPWMfrequency(GPIO17, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO17\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO18, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO18\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO22, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO22\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO27, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO27\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO17, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO17\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO18, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO18\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO22, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO22\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO27, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO27\n");
        return EXIT_FAILURE;
    }

    // Set PWM duty cycle
    if (gpioSetPWMdutyCycle(GPIO17, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMdutyCycle failed for GPIO17\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMdutyCycle(GPIO18, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMdutyCycle failed for GPIO18\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMdutyCycle(GPIO22, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMdutyCycle failed for GPIO22\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMdutyCycle(GPIO27, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMdutyCycle failed for GPIO27\n");
        return EXIT_FAILURE;
    }

    printf("PWM output set to %d on GPIO17, GPIO18, GPIO22, GPIO27\n", PWM_DUTY_CYCLE);

    // Release resources
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Error: gpioTerminate failed\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

