#define DEVICE_NAME "/dev/video0"
#define FILE_NAME "image.jpg"

int main() {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Could not open video device");
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Could not set format");
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Could not queue buffer");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_TRY_PREVIEW, NULL) < 0) {
        perror("Could not start capture");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Could not dequeue buffer");
        return EXIT_FAILURE;
    }

    FILE *file = fopen(FILE_NAME, "wb");
    if (!file) {
        perror("Could not open file for writing");
        return EXIT_FAILURE;
    }

    if (fwrite(buf.m.planes[0].m.mem_offset, 1, buf.length, file) != buf.length) {
        perror("Could not write to file");
        return EXIT_FAILURE;
    }

    fclose(file);
    close(fd);

    return EXIT_SUCCESS;
}

