#include <fcntl.h>
#include <string.h>

#define SENSOR_PATH "/sys/bus/w1/devices/28-000000000000/w1_slave"

int main(void) {
    int fd, n, i;
    char buf[512];
    float temp;

    fd = open(SENSOR_PATH, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; i++) {
        lseek(fd, 0, SEEK_SET);
        n = read(fd, buf, sizeof(buf) - 1);
        if (n < 0) {
            perror("read");
            return EXIT_FAILURE;
        }
        buf[n] = '\0';

        if (sscanf(buf, "%*s %*s t=%f", &temp) != 1) {
            fprintf(stderr, "Invalid data format\n");
            return EXIT_FAILURE;
        }

        printf("Temperature: %.2f C\n", temp / 1000.0);
        sleep(5);
    }

