#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    int pi;
    int duty_cycle = 50000;
    int max_duty_cycle = 1000000;

    pi = pigpio_start();

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon\n");
        return -1;
    }

    if (pigpio_set_mode(pi, 4, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 4 to output mode\n");
        return -1;
    }

    if (pigpio_set_mode(pi, 17, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 17 to output mode\n");
        return -1;
    }

    if (pigpio_set_mode(pi, 18, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 18 to output mode\n");
        return -1;
    }

    if (pigpio_set_PWM_range(pi, 4, max_duty_cycle) < 0) {
        printf("Failed to set PWM range for GPIO 4\n");
        return -1;
    }

    if (pigpio_set_PWM_range(pi, 17, max_duty_cycle) < 0) {
        printf("Failed to set PWM range for GPIO 17\n");
        return -1;
    }

    if (pigpio_set_PWM_range(pi, 18, max_duty_cycle) < 0) {
        printf("Failed to set PWM range for GPIO 18\n");
        return -1;
    }

    signal(SIGINT, interrupt_handler);

    while (!stop) {
        if (pigpio_set_PWM_dutycycle(pi, 4, duty_cycle) < 0) {
            printf("Failed to set PWM duty cycle for GPIO 4\n");
            return -1;
        }

        if (pigpio_set_PWM_dutycycle(pi, 17, duty_cycle) < 0) {
            printf("Failed to set PWM duty cycle for GPIO 17\n");
            return -1;
        }

        if (pigpio_set_PWM_dutycycle(pi, 18, duty_cycle) < 0) {
            printf("Failed to set PWM duty cycle for GPIO 18\n");
            return -1;
        }

        printf("Set PWM duty cycle to %d\n", duty_cycle);

        msleep(100);

        duty_cycle = (duty_cycle == max_duty_cycle) ? 0 : duty_cycle + 10000;
    }

    if (pigpio_stop(pi) < 0) {
        printf("Failed to stop pigpio\n");
        return -1;
    }

    return 0;
}

