#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT) {
        stop = 1;
    }
}

int main() {
    int pi;
    int duty_cycle = 50000;
    int period = 1000000;
    int gpio[4] = {4, 17, 18, 27};

    pi = pigpio_start();

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon\n");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpio_pin_mode(pi, gpio[i], PI_OUTPUT) < 0) {
            printf("Failed to set GPIO %d to output mode\n", gpio[i]);
            return 1;
        }

        if (gpio_set_pwm_range(pi, gpio[i], period / 100) < 0) {
            printf("Failed to set PWM range for GPIO %d\n", gpio[i]);
            return 1;
        }

        if (gpio_set_pwm_dutycycle(pi, gpio[i], duty_cycle) < 0) {
            printf("Failed to set PWM duty cycle for GPIO %d\n", gpio[i]);
            return 1;
        }
    }

    signal(SIGINT, sig_handler);

    for (int i = 0; i < 5; i++) {
        if (stop) {
            break;
        }

        printf("Cycle %d\n", i + 1);
        sleep(60);
    }

    for (int i = 0; i < 4; i++) {
        if (gpio_set_pwm_dutycycle(pi, gpio[i], 0) < 0) {
            printf("Failed to stop PWM for GPIO %d\n", gpio[i]);
            return 1;
        }
    }

    pigpio_stop(pi);

    return 0;
}

