#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

// GPIO pins to use
const int gpios[6] = {17, 18, 22, 23, 24, 25};

// PWM frequency in Hz
const int freq = 1000;

// PWM range
const int range = 1000000;

// PWM values to cycle through
const int pwm_values[5] = {0, 500, 1000, 500, 0};

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    printf("Interrupt received, stopping...\n");
    stop = 1;
}

int main() {
    int pi = pigpio_start(NULL, NULL);

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon\n");
        return 1;
    }

    for (int i = 0; i < 6; i++) {
        if (gpio_pin_mode(pi, gpios[i], PI_OUTPUT) < 0) {
            printf("Failed to set GPIO %d to output mode\n", gpios[i]);
            return 1;
        }

        if (gpio_pwm_range(pi, gpios[i], range) < 0) {
            printf("Failed to set PWM range for GPIO %d\n", gpios[i]);
            return 1;
        }

        if (gpio_pwm_freq(pi, gpios[i], freq) < 0) {
            printf("Failed to set PWM frequency for GPIO %d\n", gpios[i]);
            return 1;
        }
    }

    signal(SIGINT, signal_handler);

    int pwm_index = 0;

    while (!stop) {
        for (int i = 0; i < 6; i++) {
            if (gpio_pwm_write(pi, gpios[i], pwm_values[pwm_index]) < 0) {
                printf("Failed to set PWM value for GPIO %d\n", gpios[i]);
                return 1;
            }
        }

        printf("Applied PWM value %d\n", pwm_values[pwm_index]);

        msleep(50);

        pwm_index = (pwm_index + 1) % 5;
    }

    for (int i = 0; i < 6; i++) {
        if (gpio_pwm_write(pi, gpios[i], 0) < 0) {
            printf("Failed to set PWM value for GPIO %d\n", gpios[i]);
            return 1;
        }
    }

    pigpio_stop(pi);

    return 0;
}

