#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8

#define MAX31855_FULL_RESOLUTION 0x7FFF
#define MAX31855_CJ_OFFSET 0x0000

static int spi_open(const char *device, int mode, int max_speed_hz, int bits_per_word) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto err;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &max_speed_hz) == -1) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto err;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto err;
    }

    return fd;

err:
    close(fd);
    return -1;
}

static void spi_close(int fd) {
    close(fd);
}

static int spi_transfer(int fd, uint16_t data) {
    uint16_t buffer[1] = {data};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)buffer,
        .rx_buf = (unsigned long)buffer,
        .len = sizeof(buffer),
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) == -1) {
        fprintf(stderr, "Failed to perform SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return buffer[0];
}

int main() {
    int spi_fd = spi_open(SPI_DEVICE, SPI_MODE, SPI_MAX_SPEED_HZ, SPI_BITS_PER_WORD);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    int result = spi_transfer(spi_fd, MAX31855_FULL_RESOLUTION | MAX31855_CJ_OFFSET);
    if (result < 0) {
        spi_close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Reading: 0x%04X\n", result);

    spi_close(spi_fd);
    return EXIT_SUCCESS;
}

