#define TRIGGER_GPIO 4
#define ECHO_GPIO 17

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;

void cleanup(void)
{
    if (echo_line)
        gpiod_line_release(echo_line);
    if (trigger_line)
        gpiod_line_release(trigger_line);
    if (chip)
        gpiod_chip_close(chip);
}

int main(void)
{
    int ret;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto err_cleanup;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        goto err_cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto err_cleanup;
    }

    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        goto err_cleanup;
    }

    /* Send trigger pulse */
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    /* Wait for echo pulse */
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += 1;  /* timeout after 1 second */
    ret = gpiod_line_wait_for_rising_edge(echo_line, &ts);
    if (ret < 0) {
        if (errno == ETIMEDOUT) {
            fprintf(stderr, "Timeout while waiting for echo pulse\n");
        } else {
            perror("gpiod_line_wait_for_rising_edge");
        }
        goto err_cleanup;
    }

    printf("Echo pulse detected\n");

err_cleanup:
    cleanup();

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

