#define GPIO_LINE 17
#define VALIDITY_CHECK_VALUE 1

static void cleanup_and_exit(struct gpiod_line_request *req, int exit_code)
{
    if (req)
        gpiod_line_request_release(req);

    exit(exit_code);
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line_request *req;
    struct gpiod_line *line;
    enum gpiod_line_value value;
    int ret;

    chip = gpiod_chip_open_by_name("pinctrl-bcm2835");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        cleanup_and_exit(NULL, EXIT_FAILURE);
    }

    req = gpiod_line_request_output(line, "app-name", 0);
    if (!req) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        cleanup_and_exit(req, EXIT_FAILURE);
    }

    ret = gpiod_line_request_set_config(req, GPIOD_LINE_REQ_CONFIG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set bias configuration for GPIO line %d: %s\n",
                GPIO_LINE, strerror(-ret));
        cleanup_and_exit(req, EXIT_FAILURE);
    }

    value = gpiod_line_request_get_value(req);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                GPIO_LINE, strerror(-value));
        cleanup_and_exit(req, EXIT_FAILURE);
    }

    if (value != VALIDITY_CHECK_VALUE) {
        fprintf(stderr, "Reading from GPIO line %d failed its validity check\n",
                GPIO_LINE);
        cleanup_and_exit(req, EXIT_FAILURE);
    }

    printf("Read from GPIO line %d: %d\n", GPIO_LINE, value);

    cleanup_and_exit(req, EXIT_SUCCESS);
}

