#define REG_CTRL_MEAS 0xF4
#define REG_CONFIG 0xF5
#define REG_TEMP_XLSB 0xFC
#define REG_TEMP_LSB 0xFB
#define REG_TEMP_MSB 0xFA
#define REG_HUMIDITY_LSB 0xFD
#define REG_HUMIDITY_MSB 0xFC

int main() {
    int file, err;
    char buf[3];

    file = open("/dev/i2c-" #I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    err = ioctl(file, I2C_SLAVE, BME280_ADDR);
    if (err < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    buf[0] = REG_CTRL_HUM;
    buf[1] = 0x01;
    err = write(file, buf, 2);
    if (err < 0) {
        perror("write");
        return EXIT_FAILURE;
    }

    buf[0] = REG_CTRL_MEAS;
    buf[1] = 0x27;
    err = write(file, buf, 2);
    if (err < 0) {
        perror("write");
        return EXIT_FAILURE;
    }

    buf[0] = REG_CONFIG;
    buf[1] = 0x00;
    err = write(file, buf, 2);
    if (err < 0) {
        perror("write");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        sleep(5);

        buf[0] = REG_TEMP_XLSB;
        err = write(file, buf, 1);
        if (err < 0) {
            perror("write");
            return EXIT_FAILURE;
        }

        err = read(file, buf, 3);
        if (err < 0) {
            perror("read");
            return EXIT_FAILURE;
        }

        int32_t temperature = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
        temperature = (temperature * 17572) >> 16;

        buf[0] = REG_HUMIDITY_LSB;
        err = write(file, buf, 1);
        if (err < 0) {
            perror("write");
            return EXIT_FAILURE;
        }

        err = read(file, buf, 2);
        if (err < 0) {
            perror("read");
            return EXIT_FAILURE;
        }

        int32_t humidity = (buf[0] << 8) | buf[1];
        humidity = (humidity * 1048576) >> 16;

        printf("Temperature: %d.%02d C, Humidity: %d.%02d%%\n",
               temperature / 100, temperature % 100,
               humidity / 100, humidity % 100);
    }

    close(file);
    return EXIT_SUCCESS;
}

