    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    echo_line = gpiod_chip_get_line(chip, GPIO_ECHO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

