    while (1) {
        // Trigger the sensor
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for the echo
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 500 * 1000 * 1000 };
        if (nanosleep(&ts, NULL) != 0) {
