#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    int pi;

    pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon\n");
        return 1;
    }

    if (gpio_pin_mode(pi, 4, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 4 to output mode\n");
        return 1;
    }

    if (gpio_pin_mode(pi, 22, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 22 to output mode\n");
        return 1;
    }

    signal(SIGINT, interrupt_handler);

    while (!stop) {
        if (gpio_write(pi, 4, 1) < 0) {
            printf("Failed to set GPIO 4 high\n");
            return 1;
        }

        if (gpio_write(pi, 22, 1) < 0) {
            printf("Failed to set GPIO 22 high\n");
            return 1;
        }

        printf("GPIO 4 and 22 set to high\n");

        msleep(10);

        if (gpio_write(pi, 4, 0) < 0) {
            printf("Failed to set GPIO 4 low\n");
            return 1;
        }

        if (gpio_write(pi, 22, 0) < 0) {
            printf("Failed to set GPIO 22 low\n");
            return 1;
        }

        printf("GPIO 4 and 22 set to low\n");

        msleep(10);
    }

    if (gpio_write(pi, 4, 0) < 0) {
        printf("Failed to set GPIO 4 low\n");
        return 1;
    }

    if (gpio_write(pi, 22, 0) < 0) {
        printf("Failed to set GPIO 22 low\n");
        return 1;
    }

    pigpio_stop(pi);

    return 0;
}

