#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// GPIO pins to use
#define GPIO1 18
#define GPIO2 21
#define GPIO3 22

// PWM frequency in Hz
#define PWM_FREQ 1000

// PWM duty cycle in microseconds
#define PWM_DUTY_CYCLE_MIN 500
#define PWM_DUTY_CYCLE_MAX 2500

// Global variable to store the state of the program
volatile int running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Set up PWM on GPIO pins
    if (gpioSetPWMfrequency(GPIO1, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GPIO2, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GPIO3, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPWMdutycycle(GPIO1, PWM_DUTY_CYCLE_MIN) < 0 ||
        gpioSetPWMdutycycle(GPIO2, PWM_DUTY_CYCLE_MIN) < 0 ||
        gpioSetPWMdutycycle(GPIO3, PWM_DUTY_CYCLE_MIN) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return EXIT_FAILURE;
    }

    printf("PWM output set on GPIO %d, %d, %d with frequency %d Hz and duty cycle %d us\n",
           GPIO1, GPIO2, GPIO3, PWM_FREQ, PWM_DUTY_CYCLE_MIN);

    // Main loop
    while (running) {
        // Do nothing, wait for interrupt
    }

    // Clean up PWM on GPIO pins
    if (gpioSetPWMdutycycle(GPIO1, 0) < 0 ||
        gpioSetPWMdutycycle(GPIO2, 0) < 0 ||
        gpioSetPWMdutycycle(GPIO3, 0) < 0) {
        fprintf(stderr, "Failed to clear PWM duty cycle\n");
        return EXIT_FAILURE;
    }

    // Clean up pigpio
    gpioTerminate();

    printf("PWM output cleared on GPIO %d, %d, %d\n", GPIO1, GPIO2, GPIO3);

    return EXIT_SUCCESS;
}

