        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "led", 0)) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 100000000 };
        if (gpiod_line_wait_for_rising_edge(echo_line, &timeout) < 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        int value = gpiod_line_get_value(echo_line);
        printf("Echo value: %d\n", value);

        gpiod_line_set_value(led_line, value);

        usleep(100000);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void sig_handler(int signo) {
    if (signo == SIGINT) {
        stop = 1;
    }
}

int main() {
    int pi;

    pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("pigpio_start failed\n");
        return 1;
    }

    if (gpio_pin_mode(pi, 16, PI_OUTPUT) < 0) {
        printf("gpio_pin_mode failed\n");
        pigpio_stop(pi);
        return 1;
    }

    signal(SIGINT, sig_handler);

    while (!stop) {
        if (gpio_pwm_write(pi, 16, 0) < 0) {
            printf("gpio_pwm_write failed\n");
            pigpio_stop(pi);
            return 1;
        }

        printf("PWM ON\n");

        sleep(1);

        if (gpio_pwm_write(pi, 16, 1024) < 0) {
            printf("gpio_pwm_write failed\n");
            pigpio_stop(pi);
            return 1;
        }

        printf("PWM OFF\n");

        sleep(1);
    }

    if (gpio_pwm_write(pi, 16, 0) < 0) {
        printf("gpio_pwm_write failed\n");
        return 1;
    }

    pigpio_stop(pi);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDR 0x29
#define TCS34725_REG_ENABLE 0x80
#define TCS34725_REG_CONTROL 0x0F

int main() {
    int fd, ret;
    char buf[2];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    ret = ioctl(fd, I2C_SLAVE, TCS34725_ADDR);
    if (ret < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    buf[0] = TCS34725_REG_ENABLE;
    buf[1] = 0x03;  // Power on, no interrupts
    ret = write(fd, buf, 2);
    if (ret < 0) {
        perror("write");
        return EXIT_FAILURE;
    }

    buf[0] = TCS34725_REG_CONTROL;
    buf[1] = 0x20;  // Gain 1, integration time 2.4ms
    ret = write(fd, buf, 2);
    if (ret < 0) {
        perror("write");
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(500);  // Sleep for 0.5 seconds

        buf[0] = 0x12;  // First data byte
        ret = write(fd, buf, 1);
        if (ret < 0) {
            perror("write");
            return EXIT_FAILURE;
        }

        ret = read(fd, buf, 4);  // Read 4 data bytes
        if (ret < 0) {
            perror("read");
            return EXIT_FAILURE;
        }

        printf("Red: %d, Green: %d, Blue: %d, Clear: %d\n",
               buf[0] << 8 | buf[1], buf[2] << 8 | buf[3],
               buf[4] << 8 | buf[5], buf[6] << 8 | buf[7]);
    }

    close(fd);
    return EXIT_SUCCESS;
}

