volatile sig_atomic_t stop = 0;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    int pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pin_mode(pi, 2, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 2 to output mode.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pin_mode(pi, 3, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 3 to output mode.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pin_mode(pi, 18, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 18 to output mode.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, interrupt_handler);

    while (!stop) {
        if (gpio_pwm(pi, 2, 500) < 0) {
            printf("Failed to set PWM on GPIO 2.\n");
            return EXIT_FAILURE;
        }

        if (gpio_pwm(pi, 3, 1500) < 0) {
            printf("Failed to set PWM on GPIO 3.\n");
            return EXIT_FAILURE;
        }

        if (gpio_pwm(pi, 18, 2500) < 0) {
            printf("Failed to set PWM on GPIO 18.\n");
            return EXIT_FAILURE;
        }

        printf("PWM set on GPIO 2, GPIO 3, and GPIO 18.\n");

        sleep(5);
    }

    if (gpio_pwm(pi, 2, 0) < 0) {
        printf("Failed to clear PWM on GPIO 2.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pwm(pi, 3, 0) < 0) {
        printf("Failed to clear PWM on GPIO 3.\n");
        return EXIT_FAILURE;
    }

    if (gpio_pwm(pi, 18, 0) < 0) {
        printf("Failed to clear PWM on GPIO 18.\n");
        return EXIT_FAILURE;
    }

    printf("PWM cleared on GPIO 2, GPIO 3, and GPIO 18.\n");

    pigpio_stop(pi);

    return EXIT_SUCCESS;
}

