#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 18
#define ECHO_GPIO 23
#define MAX_ECHO_TIME 5000

struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line;

void cleanup(void)
{
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
}

int main(void)
{
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0)) {
        perror("gpiod_line_request_output");
        goto error;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        perror("gpiod_chip_get_line");
        goto error;
    }

    if (gpiod_line_request_input(echo_line, "echo")) {
        perror("gpiod_line_request_input");
        goto error;
    }

    atexit(cleanup);

    /* Trigger */
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    /* Wait for echo */
    unsigned int echo_time = 0;
    while (!gpiod_line_get_value(echo_line) && echo_time < MAX_ECHO_TIME) {
        usleep(1);
        echo_time++;
    }

    printf("Echo time: %u\n", echo_time);

    return EXIT_SUCCESS;

error:
    cleanup();
    return EXIT_FAILURE;
}

