#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void interrupt_handler(int signum) {
    stop = 1;
}

int main() {
    int pi;

    pi = pigpio_start(0, 0);

    if (pi < 0) {
        printf("Failed to connect to pigpio daemon\n");
        return 1;
    }

    if (gpio_pin_mode(pi, 18, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO 18 to output mode\n");
        return 1;
    }

    signal(SIGINT, interrupt_handler);

    while (!stop) {
        if (gpio_write(pi, 18, 1) < 0) {
            printf("Failed to set GPIO 18 high\n");
            return 1;
        }
        printf("GPIO 18 set to high\n");

        sleep(200);

        if (gpio_write(pi, 18, 0) < 0) {
            printf("Failed to set GPIO 18 low\n");
            return 1;
        }
        printf("GPIO 18 set to low\n");

        sleep(200);
    }

    if (gpio_write(pi, 18, 0) < 0) {
        printf("Failed to set GPIO 18 low\n");
        return 1;
    }

    pigpio_stop(pi);

    return 0;
}

