#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68

int main() {
    int file;
    char buffer[2];
    int i2c_addr = MPU6050_ADDR;

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, i2c_addr) < 0) {
        perror("ioctl");
        return EXIT_FAILURE;
    }

    atexit(close, file);

    while (1) {
        buffer[0] = 0x3B;
        if (write(file, buffer, 1) != 1) {
            perror("write");
            return EXIT_FAILURE;
        }

        buffer[0] = 0;
        if (read(file, buffer, 1) != 1) {
            perror("read");
            return EXIT_FAILURE;
        }

        printf("Reading: 0x%02X\n", buffer[0]);

        sleep(1);
    }

    close(file);
    return EXIT_SUCCESS;
}

void close(int file) {
    if (::close(file) < 0) {
        perror("close");
    }
}

